SELECT CASE WHEN total = 0 THEN 0.0 ELSE (elder * 100.0) / total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM posts WHERE Score > 5) AS total,
    (SELECT COUNT(*) FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE p.Score > 5 AND u.Age > 65) AS elder
);

SELECT ID
FROM Patient
WHERE "First Date" = (
  SELECT MIN("First Date")
  FROM Patient p
  WHERE EXISTS (
    SELECT 1 FROM Laboratory l
    WHERE l.ID = p.ID AND l.SSA IS NOT NULL AND l.SSA NOT IN('negative','0')
  )
);

SELECT CASE WHEN total=0 THEN 0 ELSE ROUND(100.0*high/total,2) END AS percentage FROM (
  SELECT
    (SELECT COUNT(DISTINCT ID) FROM Patient WHERE SEX='F') AS total,
    (SELECT COUNT(DISTINCT Laboratory.ID) FROM Laboratory JOIN Patient ON Patient.ID=Laboratory.ID WHERE Patient.SEX='F' AND Laboratory.UA>6.5) AS high
);

SELECT CASE WHEN denom=0 THEN 0 ELSE 100.0*high/denom END AS percent FROM (
  SELECT
    (SELECT COUNT(DISTINCT l1.ID)
     FROM Laboratory l1 JOIN Patient p1 ON l1.ID = p1.ID
     WHERE p1.SEX='F' AND l1.UA IS NOT NULL AND l1.UA > 6.5
    ) AS high,
    (SELECT COUNT(DISTINCT l2.ID)
     FROM Laboratory l2 JOIN Patient p2 ON l2.ID = p2.ID
     WHERE p2.SEX='F' AND l2.UA IS NOT NULL
    ) AS denom
);

answer_sql:
