    (SELECT COUNT(DISTINCT l2.ID)
     FROM Laboratory l2 JOIN Patient p2 ON l2.ID = p2.ID
     WHERE p2.SEX='F' AND l2.UA IS NOT NULL
    ) AS denom
);

